'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0)};
const p={"gamma":0.9};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 固定交互顺序
Object.assign(s, ((s,p)=>({rewards:[1,0,2]}))(s, p));
// 把未来奖励折回起点
Object.assign(s, ((s,p)=>({discounted:s.rewards.map((r,t)=>r*p.gamma**t)}))(s, p));
// 合成一次回报
Object.assign(s, ((s,p)=>({return:H.sum(s.discounted)}))(s, p));
// 比较即时和未来收益
Object.assign(s, ((s,p)=>({immediate:s.rewards[0],future:s.return-s.rewards[0]}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0)};
const p={"gamma":0.9,"success":0.8};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 列出转移的所有结果
Object.assign(s, ((s,p)=>({probabilities:[p.success,1-p.success],oldValue:1}))(s, p));
// 对转移结果求期望
Object.assign(s, ((s,p)=>({contributions:[p.success*2,(1-p.success)*p.gamma*s.oldValue]}))(s, p));
// 进行一次 Bellman 更新
Object.assign(s, ((s,p)=>({nextValue:H.sum(s.contributions)}))(s, p));
// 独立解固定点
Object.assign(s, ((s,p)=>({fixedPoint:2*p.success/(1-(1-p.success)*p.gamma),residual:Math.abs(s.nextValue-s.oldValue)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"gamma":0.9,"sweeps":3};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 定义两状态和终点
Object.assign(s, ((s,p)=>({values:[0,0]}))(s, p));
// 同步执行价值迭代
Object.assign(s, ((s,p)=>{let v=s.values.slice(),history=[v.slice()];for(let k=0;k<p.sweeps;k++){v=[Math.max(1,p.gamma*v[1]),2];history.push(v.slice());}return {values:v,history};})(s, p));
// 用更新后的价值选择动作
Object.assign(s, ((s,p)=>({actionValues:[1,p.gamma*s.values[1]]}))(s, p));
// 给出贪心策略
Object.assign(s, ((s,p)=>({action:s.actionValues[0]>=s.actionValues[1]?'退出':'前进',value:Math.max(...s.actionValues)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"alpha":0.5,"gamma":0.9,"terminal":"no"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 取出一条经验
Object.assign(s, ((s,p)=>({value:1,nextValue:2,reward:0}))(s, p));
// 构造单步目标
Object.assign(s, ((s,p)=>({target:s.reward+(p.terminal==='yes'?0:p.gamma*s.nextValue)}))(s, p));
// 计算 TD 误差
Object.assign(s, ((s,p)=>({delta:s.target-s.value}))(s, p));
// 只走一步更新
Object.assign(s, ((s,p)=>({updated:s.value+p.alpha*s.delta}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"alpha":0.5,"gamma":0.9,"method":"q"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 记录行为策略的一次转移
Object.assign(s, ((s,p)=>({q:0,reward:1,nextQ:[2,4],nextAction:0}))(s, p));
// 区分目标策略
Object.assign(s, ((s,p)=>({bootstrap:p.method==='q'?Math.max(...s.nextQ):s.nextQ[s.nextAction]}))(s, p));
// 形成样本目标
Object.assign(s, ((s,p)=>({target:s.reward+p.gamma*s.bootstrap}))(s, p));
// 更新被访问的Q
Object.assign(s, ((s,p)=>({updated:s.q+p.alpha*(s.target-s.q)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0)};
const p={"epsilon":0.2,"draw":0.7};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先声明贪心动作和平分规则
Object.assign(s, ((s,p)=>({q:[1,3,2],greedy:1}))(s, p));
// 分配 ε-greedy 概率
Object.assign(s, ((s,p)=>({probabilities:s.q.map((_,i)=>p.epsilon/3+(i===s.greedy?1-p.epsilon:0))}))(s, p));
// 构造累计区间
Object.assign(s, ((s,p)=>({cdf:s.probabilities.map((_,i)=>H.sum(s.probabilities.slice(0,i+1)))}))(s, p));
// 选出本次动作
Object.assign(s, ((s,p)=>({action:s.cdf.findIndex(x=>p.draw<x),total:H.sum(s.probabilities)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={dot:(a,b)=>a.reduce((v,x,i)=>v+x*b[i],0)};
const p={"alpha":0.1,"target":3};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 用特征共享参数
Object.assign(s, ((s,p)=>({features:[1,2],weights:[.5,.5]}))(s, p));
// 前向估计
Object.assign(s, ((s,p)=>({prediction:H.dot(s.features,s.weights)}))(s, p));
// 冻结目标后取半梯度
Object.assign(s, ((s,p)=>({delta:p.target-s.prediction,gradient:s.features.map(x=>(s.prediction-p.target)*x)}))(s, p));
// 更新共享权重
Object.assign(s, ((s,p)=>({updated:s.weights.map((w,i)=>w-p.alpha*s.gradient[i]),newPrediction:H.dot(s.weights.map((w,i)=>w-p.alpha*s.gradient[i]),s.features)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={softmax:xs=>{const m=Math.max(...xs),e=xs.map(x=>Math.exp(x-m)),z=e.reduce((a,b)=>a+b,0);return e.map(x=>x/z);}};
const p={"logit":0,"advantage":1,"alpha":0.2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 把logit变成随机策略
Object.assign(s, ((s,p)=>({probabilities:H.softmax([0,p.logit])}))(s, p));
// 对已采到的动作1取对数梯度
Object.assign(s, ((s,p)=>({score:1-s.probabilities[1]}))(s, p));
// 用优势加权
Object.assign(s, ((s,p)=>({gradient:p.advantage*s.score}))(s, p));
// 执行梯度上升并重新计算
Object.assign(s, ((s,p)=>({updatedLogit:p.logit+p.alpha*s.gradient,newProbability:H.softmax([0,p.logit+p.alpha*s.gradient])[1]}))(s, p));
console.log(JSON.stringify(s,null,2));
